<summary>proof-live.ts</summary>

```ts
import { setTimeout as sleep } from "node:timers/promises";
import { resolveGoogleMeetConfig } from "./extensions/google-meet/src/config.ts";
import {
  createGoogleMeetChromeNodeInvokePolicy,
  GOOGLE_MEET_CHROME_NODE_COMMAND,
} from "./extensions/google-meet/src/node-invoke-policy.ts";
import {
  startNodeAgentAudioBridge,
  startNodeRealtimeAudioBridge,
} from "./extensions/google-meet/src/realtime-node.ts";

const invalidPolicyCalls: unknown[] = [];
const validPolicyCalls: unknown[] = [];
const policy = createGoogleMeetChromeNodeInvokePolicy(resolveGoogleMeetConfig({}));
const invalidPolicy = await policy.handle({
  nodeId: "node-1",
  command: GOOGLE_MEET_CHROME_NODE_COMMAND,
  params: { action: "pushAudio", bridgeId: "bridge-1", base64: "not-base64!" },
  config: {} as never,
  pluginConfig: {},
  invokeNode: async (call) => {
    invalidPolicyCalls.push(call);
    return { ok: true, payload: {} };
  },
});
const validPolicy = await policy.handle({
  nodeId: "node-1",
  command: GOOGLE_MEET_CHROME_NODE_COMMAND,
  params: {
    action: "pushAudio",
    bridgeId: "bridge-1",
    base64: Buffer.from([1, 2, 3]).toString("base64"),
  },
  config: {} as never,
  pluginConfig: {},
  invokeNode: async (call) => {
    validPolicyCalls.push(call);
    return { ok: true, payload: { ok: true } };
  },
});

async function runRealtimeBridge() {
  const sentAudio: number[][] = [];
  let pullCount = 0;
  let releaseIdlePull: (() => void) | undefined;
  const runtime = {
    nodes: {
      invoke: async ({ params }: { params?: { action?: string } }) => {
        if (params?.action === "pullAudio") {
          pullCount += 1;
          if (pullCount === 1) {
            return { bridgeId: "bridge-1", base64: "not-base64!" };
          }
          if (pullCount === 2) {
            return { bridgeId: "bridge-1", base64: Buffer.from([5, 4, 3]).toString("base64") };
          }
          await new Promise<void>((resolve) => {
            releaseIdlePull = resolve;
          });
          return { bridgeId: "bridge-1" };
        }
        releaseIdlePull?.();
        releaseIdlePull = undefined;
        return { ok: true };
      },
    },
  };
  const bridge = {
    connect: async () => {},
    sendAudio: (audio: Buffer) => sentAudio.push([...audio]),
    setMediaTimestamp: () => {},
    submitToolResult: () => {},
    acknowledgeMark: () => {},
    close: () => {},
    triggerGreeting: () => {},
    isConnected: () => true,
  };
  const provider = {
    id: "openai",
    label: "OpenAI",
    autoSelectOrder: 1,
    resolveConfig: ({ rawConfig }: { rawConfig: unknown }) => rawConfig,
    isConfigured: () => true,
    createBridge: () => bridge,
  };
  const logger = { info() {}, warn() {}, error() {}, debug() {} };
  const handle = await startNodeRealtimeAudioBridge({
    config: resolveGoogleMeetConfig({ realtime: { provider: "openai", model: "gpt-realtime" } }),
    fullConfig: {} as never,
    runtime: runtime as never,
    meetingSessionId: "meet-1",
    nodeId: "node-1",
    bridgeId: "bridge-1",
    logger,
    providers: [provider as never],
  });
  try {
    for (let i = 0; i < 20 && sentAudio.length === 0; i += 1) {
      await sleep(50);
    }
    const health = handle.getHealth();
    return {
      pullCount,
      providerAudioChunks: sentAudio,
      malformedChunkForwarded: sentAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from("not-base64!", "base64"))
      ),
      validChunkForwarded: sentAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from([5, 4, 3]))
      ),
      lastInputBytes: health.lastInputBytes,
      consecutiveInputErrors: health.consecutiveInputErrors,
    };
  } finally {
    await handle.stop();
  }
}

async function runAgentBridge() {
  const sttAudio: number[][] = [];
  let pullCount = 0;
  let releaseIdlePull: (() => void) | undefined;
  const runtime = {
    nodes: {
      invoke: async ({ params }: { params?: { action?: string } }) => {
        if (params?.action === "pullAudio") {
          pullCount += 1;
          if (pullCount === 1) {
            return { bridgeId: "bridge-1", base64: "not-base64!" };
          }
          if (pullCount === 2) {
            return { bridgeId: "bridge-1", base64: Buffer.from([6, 5, 4]).toString("base64") };
          }
          await new Promise<void>((resolve) => {
            releaseIdlePull = resolve;
          });
          return { bridgeId: "bridge-1" };
        }
        releaseIdlePull?.();
        releaseIdlePull = undefined;
        return { ok: true };
      },
    },
  };
  const sttSession = {
    connect: async () => {},
    sendAudio: (audio: Buffer) => sttAudio.push([...audio]),
    close: () => {},
    isConnected: () => true,
  };
  const provider = {
    id: "openai",
    label: "OpenAI",
    defaultModel: "gpt-4o-transcribe",
    autoSelectOrder: 1,
    resolveConfig: ({ rawConfig }: { rawConfig: unknown }) => rawConfig,
    isConfigured: () => true,
    createSession: () => sttSession,
  };
  const logger = { info() {}, warn() {}, error() {}, debug() {} };
  const handle = await startNodeAgentAudioBridge({
    config: resolveGoogleMeetConfig({
      chrome: { audioFormat: "g711-ulaw-8khz" },
      realtime: { provider: "openai", agentId: "jay", introMessage: "" },
    }),
    fullConfig: {} as never,
    runtime: runtime as never,
    meetingSessionId: "meet-1",
    nodeId: "node-1",
    bridgeId: "bridge-1",
    logger,
    providers: [provider as never],
  });
  try {
    for (let i = 0; i < 20 && sttAudio.length === 0; i += 1) {
      await sleep(50);
    }
    const health = handle.getHealth();
    return {
      pullCount,
      sttAudioChunks: sttAudio,
      malformedChunkForwarded: sttAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from("not-base64!", "base64"))
      ),
      validChunkForwarded: sttAudio.some((chunk) =>
        Buffer.from(chunk).equals(Buffer.from([6, 5, 4]))
      ),
      lastInputBytes: health.lastInputBytes,
      consecutiveInputErrors: health.consecutiveInputErrors,
    };
  } finally {
    await handle.stop();
  }
}

console.log(JSON.stringify({
  productionPath: [
    "createGoogleMeetChromeNodeInvokePolicy",
    "startNodeRealtimeAudioBridge",
    "startNodeAgentAudioBridge",
    "runtime.nodes.invoke(pullAudio)",
    "provider.sendAudio/transcriptionSession.sendAudio",
  ],
  policy: {
    invalidOk: invalidPolicy.ok,
    invalidMessage: invalidPolicy.message,
    invalidDispatches: invalidPolicyCalls.length,
    validOk: validPolicy.ok,
    validDispatches: validPolicyCalls.length,
  },
  realtime: await runRealtimeBridge(),
  agent: await runAgentBridge(),
}, null, 2));
```

